ALTER TABLE "paid_reading_attempts" DROP CONSTRAINT "paid_attempts_section_check";--> statement-breakpoint
ALTER TABLE "paid_reading_runs" DROP CONSTRAINT "paid_runs_contract_check";--> statement-breakpoint
ALTER TABLE "paid_reading_runs" DROP CONSTRAINT "paid_runs_manifest_check";--> statement-breakpoint
ALTER TABLE "paid_reading_runs" DROP CONSTRAINT "paid_runs_state_check";--> statement-breakpoint
ALTER TABLE "paid_reading_attempts" ADD CONSTRAINT "paid_attempts_section_check" CHECK ("paid_reading_attempts"."section" in ('overview','sun','moon','ascendant','aspects','houses','planets','nodes','planetaryYear','transits','guidance') and "paid_reading_attempts"."phase" in ('primary','repair'));--> statement-breakpoint
ALTER TABLE "paid_reading_runs" ADD CONSTRAINT "paid_runs_contract_check" CHECK ("paid_reading_runs"."profile" in ('paid-core-v1','paid-rich-v1') and "paid_reading_runs"."allowance_policy" = 'one-per-account-utc-month-v1' and "paid_reading_runs"."ceiling_micros" = 10000000 and "paid_reading_runs"."locale" in ('en','es') and "paid_reading_runs"."period" ~ '^[0-9]{4}-(0[1-9]|1[0-2])$');--> statement-breakpoint
ALTER TABLE "paid_reading_runs" ADD CONSTRAINT "paid_runs_manifest_check" CHECK (("paid_reading_runs"."profile" = 'paid-core-v1' and "paid_reading_runs"."expected_sections" = '["overview","sun","moon","ascendant","aspects","houses","planets","nodes","guidance"]'::jsonb) or ("paid_reading_runs"."profile" = 'paid-rich-v1' and "paid_reading_runs"."expected_sections" = '["overview","sun","moon","ascendant","aspects","houses","planets","nodes","planetaryYear","transits","guidance"]'::jsonb));--> statement-breakpoint
ALTER TABLE "paid_reading_runs" ADD CONSTRAINT "paid_runs_state_check" CHECK ("paid_reading_runs"."completed_sections" between 0 and jsonb_array_length("paid_reading_runs"."expected_sections") and "paid_reading_runs"."status" in ('queued','preparing','generating','completed','partial','failed','stopped','attention') and ("paid_reading_runs"."status" not in ('completed','partial') or "paid_reading_runs"."consumed_at" is not null));